<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3">Expenses</h1></div>
<div id="msg" class="alert d-none"></div>
<div class="card shadow-sm mb-3"><div class="card-body"><form id="form"><div class="row g-2"><div class="col-md-2"><input name="expense_date" type="date" class="form-control" value="<?=e($today)?>"></div><div class="col-md-3"><select name="category_id" class="form-select" required><?php foreach($categories as $c):?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input name="amount" class="form-control" inputmode="decimal" placeholder="Amount" required></div><div class="col-md-2"><input name="counter_id" class="form-control" placeholder="Counter ID" required></div><div class="col-md-3"><input name="reference_no" class="form-control" placeholder="Reference no."></div><div class="col-md-4"><input name="payee" class="form-control" placeholder="Payee"></div><div class="col-md-8"><input name="notes" class="form-control" placeholder="Notes"></div><div class="col-12"><button class="btn btn-primary">Post Expense</button></div></div></form></div></div>
<div class="card shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Date</th><th>Category</th><th>Amount</th><th>Counter</th><th>Status</th><th></th></tr></thead><tbody id="rows"></tbody></table></div></div></div>
<script>
$(function(){const b=<?=json_encode(url('/'))?>;function msg(t,c='success'){$('#msg').removeClass('d-none alert-success alert-danger').addClass('alert-'+c).text(t);}function load(){$.getJSON(b+'expenses/data',r=>{let x=$('#rows').empty();(r.data.rows||[]).forEach(a=>x.append('<tr><td>'+a.expense_date+'</td><td>'+esc(a.category_name)+'</td><td>'+Number(a.amount).toFixed(2)+'</td><td>'+esc(a.counter_name||'')+'</td><td>'+esc(a.status)+'</td><td>'+(a.status==='POSTED'?'<button class="btn btn-sm btn-outline-danger void" data-id="'+a.id+'">Void</button>':'')+'</td></tr>'));});}function esc(v){return $('<div>').text(v??'').html();}$('#form').on('submit',function(e){e.preventDefault();$.post(b+'expenses',$(this).serialize()).done(r=>{msg(r.message,r.ok?'success':'danger');if(r.ok){this.reset();load();}}).fail(x=>msg(x.responseJSON?.message||'Expense failed.','danger'));});$('#rows').on('click','.void',function(){const reason=prompt('Void reason');if(!reason)return;$.post(b+'expenses/void',{id:$(this).data('id'),reason}).done(r=>{msg(r.message,r.ok?'success':'danger');if(r.ok)load();});});load();});
</script>